CREATE TABLE `cert_alert_records` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号（T 轨）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者（SYSTEM）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间（=触发时间 triggered_at）',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除（恒 0，只追加）',
  `cert_id` bigint DEFAULT NULL COMMENT '关联证照 certificate_info.id（EXPIRY 等证照类填；QUAL_EXPIRY 资质类置 NULL，用 ref_* 定位）',
  `alert_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EXPIRY' COMMENT '预警类型 code：EXPIRY/REVIEW/RENEWAL',
  `alert_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WARNING' COMMENT '档位 code：INFO/WARNING/CRITICAL（90/60→INFO、30→WARNING、7→CRITICAL，多档取最严重）',
  `idempotent_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键：cert_id:alert_type:yyyyMMdd 触发日期，防定时任务重启/重跑重复（v3.3 §九）',
  `alert_message` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预警内容（如“将于 30 天后到期”）',
