  `notify_target` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收人 ID/角色（脱敏；当前默认 TENANT_ADMIN 占位）',
  `notify_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '通知状态 code：PENDING/SENDING/SUCCESS/FAILED/DEAD（与 cert_notify_outbox 联动可靠投递+失败补偿）',
  `handled` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否已处理（处理闭环，如“已续期”）',
  `handled_by` bigint DEFAULT NULL COMMENT '处理人',
  `handled_at` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_note` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理备注',
  `archive_status` tinyint NOT NULL DEFAULT '0' COMMENT '归档状态：0 在库 /1 已归档（已处理满 6 个月归档、保留 2 年，定时任务处理）',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本（handled/notify_status CAS 更新防并发覆盖，v3.3 §九）',
  `ref_type` varchar(24) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务对象大类 code（QUAL_EXPIRY 用）：QUAL 企业资质/SAFETY_PERMIT 安许/STAFF 资质人员',
  `ref_id` bigint DEFAULT NULL COMMENT '业务对象主键（qual_id/permit_id/staff_id）',
  `ref_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务对象显示名（脱敏）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_alert_idempotent` (`idempotent_key`),
  KEY `idx_alert_handle` (`tenant_id`,`handled`,`triggered_at` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='预警记录（T 轨 · 幂等防重跑）';
