  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `cert_id` bigint NOT NULL COMMENT '关联证照（冗余父键 certificate_info.id，§5 四-2）',
  `file_category` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ORIGINAL' COMMENT '文件类别 code：ORIGINAL 原件/COPY 副本/CHANGE_PAGE 变更页/RENEWAL_PAGE 延续页/E_CERT 电子证照/OTHER（自查“有原件/有电子证照”按 ORIGINAL/E_CERT 且 is_current=TRUE 判定，v3.4 §18.1-2）',
  `file_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名',
