  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256（防篡改/去重，§5 三-5）',
  `file_format` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件格式：PDF/JPG/PNG/OFD（OFD=GB/T 36905 版式电子证照）',
  `file_size` bigint NOT NULL COMMENT '字节数',
  `copy_creation_time` datetime DEFAULT NULL COMMENT '加注件制作时间（GB/T 36903 5.4.1 JZJZZSJ；仅加注件行填写）',
  `copy_creator` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加注件制作者（GB/T 36903 5.4.2 JZJZZZ）',
  `copy_cause` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加注件制作事由（GB/T 36903 5.4.3 JZJZZSY，一般同步水印）',
  `copy_expiring_time` datetime DEFAULT NULL COMMENT '加注件有效期截止时间（GB/T 36903 5.4.4 JZJYXQJZSJ）',
  `version` int NOT NULL DEFAULT '1' COMMENT '同类别文件版本号（只追加，旧版本只读保留）',
  `is_current` bit(1) NOT NULL DEFAULT b'1' COMMENT '当前生效版本（自查只取 TRUE 行）',
  `virus_scan_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '病毒扫描状态 code：PENDING/CLEAN/INFECTED（上传须 CLEAN 才可预览/下载）',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `voided` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否作废（F2 软删留痕）',
  `void_reason` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作废原因（留痕展示用）',
  `voided_at` datetime DEFAULT NULL COMMENT '作废时间（留痕用）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_file_hash` (`cert_id`,`file_hash`,`deleted`,`tenant_id`),
  UNIQUE KEY `uk_cert_cat_version` (`cert_id`,`file_category`,`version`,`deleted`,`tenant_id`),
  KEY `idx_cert_current` (`cert_id`,`is_current`,`deleted`),
  KEY `idx_cert_voided` (`cert_id`,`voided`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='证照文件版本表（T 轨）';
