  `biz_domain` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务对象域 code：CERT 证照台账/PERSON_CERT 员工证书/ENTERPRISE_QUAL 企业资质/SAFETY_PERMIT 安许证',
  `biz_id` bigint NOT NULL COMMENT '业务对象主键（certificate_info.id / personnel_certificate.id / enterprise_qualification.id / qualification_safety_permit.id）',
  `ref_name` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务对象名称快照（防主档改名后无法复算）',
  `ref_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书编号快照',
  `ent_id` bigint DEFAULT NULL COMMENT '归属企业（便于按企业聚合生命周期台账）',
  `lifecycle_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生命周期类型 code：CHANGE 变更/RENEW 续期/REVOKE 注销吊销/ANNUAL 年检',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '状态 code：PENDING 待办/REVIEWING 审核中/APPROVED 通过/REJECTED 驳回/EFFECTIVE 已生效',
  `apply_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请单号（对外可引用；同类型同日同对象唯一）',
  `change_group_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更归组号（同一次变更申请涉及多字段时共用一组）',
  `field_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更字段名（台账列名，如 cert_status/valid_to/cert_level）',
  `old_value` text COLLATE utf8mb4_unicode_ci COMMENT '变更前值',
  `new_value` text COLLATE utf8mb4_unicode_ci COMMENT '变更后值（生效时同步主档）',
  `change_summary` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更摘要',
  `renewal_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '续期类型 code：RENEW 延续/REISSUE 补换证（补换证可能产生新编号）',
  `old_valid_from` date DEFAULT NULL COMMENT '续期前有效期起始（快照）',
  `old_valid_to` date DEFAULT NULL COMMENT '续期前有效期止（快照）',
  `new_valid_from` date DEFAULT NULL COMMENT '续期后有效期起始（生效回写主档）',
  `new_valid_to` date DEFAULT NULL COMMENT '续期后有效期止（生效回写主档；驱动下一轮到期预警）',
  `new_next_review_date` date DEFAULT NULL COMMENT '下次年检日（生效回写主档 next_review_date）',
  `new_cert_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新证书编号（补换证产生新编号时填写）',
  `result_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批复/许可决定文号',
  `revoke_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '注销吊销类型 code：REVOKE 吊销/CANCEL 注销/SUSPEND 暂扣/RESTORE 恢复',
  `revoke_authority` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '决定机关',
  `revoke_reason` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '决定事由',
  `revoke_effective_at` date DEFAULT NULL COMMENT '决定生效日期',
  `review_year` smallint DEFAULT NULL COMMENT '年检年度（如 2026）',
  `review_date` date DEFAULT NULL COMMENT '年检日期',
  `review_result` tinyint DEFAULT NULL COMMENT '年检/审查结论：NULL 未出结论 / 0 不通过 / 1 通过',
  `new_cert_file_id` bigint DEFAULT NULL COMMENT '新文件 id（变更页/延续页/新证扫描件，经 FileApi 上传后登记）',
  `evidence_file_ids` json DEFAULT NULL COMMENT '佐证材料文件 id 列表（决定书/年检材料/变更证明）',
  `applied_by` bigint DEFAULT NULL COMMENT '申请人（用户 id）',
  `applied_at` datetime DEFAULT NULL COMMENT '申请时间',
  `handled_by` bigint DEFAULT NULL COMMENT '办理人（审批/登记人）',
  `handled_at` datetime DEFAULT NULL COMMENT '办理时间',
  `effective_at` datetime DEFAULT NULL COMMENT '生效时间（回写主档的时间，审计用）',
  `idempotent_key` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '幂等键（biz_domain:biz_id:lifecycle_type:apply_no），防重复提交',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本（状态机 CAS）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lifecycle_idem` (`tenant_id`,`idempotent_key`,`deleted`),
  KEY `idx_lifecycle_biz` (`tenant_id`,`biz_domain`,`biz_id`,`lifecycle_type`,`status`),
  KEY `idx_lifecycle_status` (`tenant_id`,`lifecycle_type`,`status`,`applied_at`),
  KEY `idx_lifecycle_group` (`tenant_id`,`change_group_id`),
  KEY `idx_lifecycle_review` (`tenant_id`,`review_year`,`review_result`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='证件/资质生命周期记录（变更/续期/注销吊销/年检，只追加）';
