  `last_error` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次错误信息（排障）',
  `sent_at` datetime DEFAULT NULL COMMENT '发送成功时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_outbox_biz` (`biz_type`,`biz_id`,`channel`,`receiver`),
  KEY `idx_outbox_retry` (`send_status`,`next_retry_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知发送发件箱（T 轨 · 可靠投递）';
