  `verify_by` bigint DEFAULT NULL COMMENT '发起人（含 SYSTEM，用户 ID）',
  `verified_at` datetime NOT NULL COMMENT '验真完成时间',
  `idempotent_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键：<种类>:cert_id:channel:<窗口桶起点秒>（种类=INFO/FILE），仅作并发兜底；幂等主判定是"滑动窗口内最近一次验真"，窗口来自配置 cert.verify.idempotent.window.seconds（v3.3 §17.5 UNIQUE）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_verify_idempotent` (`idempotent_key`),
  KEY `idx_verify_cert_time` (`tenant_id`,`cert_id`,`verified_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='验真历史表（T 轨 · 只追加 · 幂等防重）';
