  `cert_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证照名称（GB/T 36903 5.2.1 ZZMC/certificateName；AI 自查名称匹配）',
  `cert_no` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证书编号（建办市51号 ZSBH；随证型/码制浮动按 varchar(128) 落，开发规范 §5.2；租户内唯一）',
  `cert_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证照大类（台账分类 code：ADMIN_LICENSE/SYSTEM_CERT/PERSON_QUAL/HONOR/OTHER，v3.3 §二）',
  `cert_category_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证照类型代码（GB/T 36902 5.2.2 ZZLXDM 21 位/行标，如 11100000000013338W002）',
  `cert_level` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资质等级（一级/甲级…）',
  `cert_scope` text COLLATE utf8mb4_unicode_ci COMMENT '许可/业务范围（较长文本随表存储，§5 三-1）',
  `holder_name` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '持证主体（GB/T 36903 5.2.8 CZZT/certificateHolderName；AI 自查一票否决）',
  `holder_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ORG' COMMENT '持证主体类别 code：ORG/PERSON/EXTERNAL（v3.3 §二）',
  `holder_id` bigint DEFAULT NULL COMMENT '关联档案 ID（人员/企业档案）',
  `issuing_authority` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '颁发/许可机关（契约标为可选；原 NOT NULL 与契约冲突）',
  `issuing_authority_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证照颁发机构代码（GB/T 36903 5.2.6 ZZBFJGDM，统一社会信用代码 GB 32100）',
  `issue_date` date DEFAULT NULL COMMENT '证照颁发日期（GB/T 36903 5.2.7 ZZBFRQ；展示用）',
  `valid_from` date DEFAULT NULL COMMENT '证照有效期起始日期（GB/T 36903 5.2.12 ZZYXQQSRQ；自查覆盖判断）',
  `valid_to` date DEFAULT NULL COMMENT '证照有效期截止日期（GB/T 36903 5.2.13 ZZYXQJZRQ；NULL=长期；自查余期+到期预警扫描）',
  `applicable_industries` json DEFAULT NULL COMMENT '适用行业（结构化 JSON）',
  `applicable_regions` json DEFAULT NULL COMMENT '适用地区（结构化 JSON）',
  `annual_review_cycle` smallint DEFAULT NULL COMMENT '年检周期（月），预警用',
  `next_review_date` date DEFAULT NULL COMMENT '下次年检日（自查+年检预警）',
  `is_exclusive_locked` bit(1) NOT NULL DEFAULT b'0' COMMENT '排他锁定（在建项目占用）',
  `lock_info` json DEFAULT NULL COMMENT '锁定明细（结构化 JSON）',
  `e_cert_ident` varchar(96) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电子证照标识（GB/T 36904 6 段编码+MOD37,36，≤74 位；51号 DZZZBZ；v3.4 起仅存标识，文件实体见 cert_file_versions）',
  `cert_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '台账状态 code（对齐 51号 ZZZT：ACTIVE/EXPIRING_SOON/EXPIRED/SUSPENDED/REVOKED/CANCELLED；自查只认 ACTIVE）',
  `verification_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNVERIFIED' COMMENT '验真状态 code：UNVERIFIED/VERIFYING/VERIFIED/INVALID（与 cert_status 独立，自查不认 INVALID）',
  `last_verified_at` datetime DEFAULT NULL COMMENT '最近验真时间',
  `verify_api_source` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '验真来源',
  `official_verify_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '官方核验链接（展示）',
  `source_channel` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '数据来源 code：MANUAL/IMPORT/OCR/API_SYNC',
  `extra_props` json DEFAULT NULL COMMENT '动态扩展（结构化 JSON，如 cmmi_level）',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注（较长文本随表存储，§5 三-1）',
  `version` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本（开发规范 §4.5 乐观锁款；更新走 WHERE id=? AND version=?）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_no` (`cert_no`,`deleted`,`tenant_id`),
  KEY `idx_cert_status` (`cert_status`),
  KEY `idx_cert_valid_to` (`valid_to`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='证照台账主表（T 轨 · cert_ 前缀例外）';
