  `person_id` bigint NOT NULL COMMENT '持证人（bidding_personnel_profile.id）',
  `cert_type` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证书类型 code：ID_CARD/EDUCATION_CERT/DEGREE_CERT/TITLE_CERT/REG_PRACTICE_CERT/SAFETY_ASSESS_CERT/SKILL_CERT/TRAINING_CERT/OTHER',
